  var HTML = "<header class=\"top\">\n  <div class=\"wrap\">\n    <a class=\"brand\" href=\"#top\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/asra-logo.png\" alt=\"ASRA roundel logo\"><span><b>Arizona State Referee Administration</b><small>US Soccer State Referee Committee for Arizona</small></span></a>\n    <nav class=\"nav\" aria-label=\"Main\">\n      <a href=\"#become\" style=\"--c:var(--yellow)\">Become a Referee</a>\n      <a href=\"#games\" style=\"--c:var(--green)\">Find Games</a>\n      <a href=\"#resources\" style=\"--c:var(--blue)\">Resources</a>\n      <a href=\"#fitness\" style=\"--c:var(--red)\">Upgrades &amp; Fitness</a>\n    </nav>\n    <div class=\"util\"><a class=\"recert\" href=\"/recertify\">Recertify</a><a class=\"abuse\" href=\"https://request.azref.com/abuse/\">Report abuse</a></div>\n  </div>\n  <div class=\"kitline\" aria-hidden=\"true\"><i style=\"--c:var(--yellow)\"></i><i style=\"--c:var(--green)\"></i><i style=\"--c:var(--blue)\"></i><i style=\"--c:var(--red)\"></i></div>\n</header>\n\n<main id=\"top\">\n<!-- Announcement bar: filled from the CMS collection \"Homepage Announcements\" (announce.js in the mockup). -->\n<a class=\"recert-bar\" id=\"announce\" href=\"/recertify\"><span class=\"wrap\"><span class=\"rb-t\"><small id=\"anK\">Already a referee?</small><strong id=\"anT\">Recertify for 2027</strong><i id=\"anP\">Online · about 5 hours · $80 all in</i></span><em><span id=\"anB\">Recertify now</span> <svg width=\"18\" height=\"13\" viewBox=\"0 0 22 16\" aria-hidden=\"true\"><path d=\"M0 8h19M13 1l7 7-7 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"></path></svg></em></span></a>\n<div class=\"lockers\">\n  <a class=\"locker\" href=\"#become\" style=\"--c:var(--yellow)\">\n    <span class=\"ph\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/crew-yellow.jpg\" alt=\"Three young Arizona referees in yellow kits, arms around each other\"></span>\n    <span class=\"tag\"><h2>Become a Referee</h2><p>Age 13 and up. Four steps. Next in-person class: Tucson, Sat Oct 3.</p>\n      <span class=\"more\">Get certified <svg width=\"22\" height=\"16\" viewBox=\"0 0 22 16\" aria-hidden=\"true\"><path d=\"M0 8h19M13 1l7 7-7 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"></path></svg></span></span>\n  </a>\n  <div class=\"locker has-two\" style=\"--c:var(--green)\">\n    <span class=\"ph\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/crew-green.jpg\" alt=\"A referee crew in green kits at a national championship\" style=\"object-position:30% 30%\"></span>\n    <span class=\"tag\"><h2><a class=\"stretch\" href=\"#games\">Find Games</a></h2><p id=\"lockerGames\">77 events this season, rated by level.</p>\n      <span class=\"two\"><span class=\"more\">See events <svg width=\"22\" height=\"16\" viewBox=\"0 0 22 16\" aria-hidden=\"true\"><path d=\"M0 8h19M13 1l7 7-7 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"></path></svg></span><a class=\"faq-pill\" href=\"/assignors\">Find an assignor</a></span></span>\n  </div>\n  <div class=\"locker has-two\" style=\"--c:var(--blue)\">\n    <span class=\"ph\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/ar-flag-run.jpg\" alt=\"An assistant referee in blue running the line with his flag\" style=\"object-position:50% 20%\"></span>\n    <span class=\"tag\"><h2><a class=\"stretch\" href=\"#resources\">Resources</a></h2><p>FAQs, assignors, forms and the Laws of the Game.</p>\n      <span class=\"two\"><span class=\"more\">Open <svg width=\"22\" height=\"16\" viewBox=\"0 0 22 16\" aria-hidden=\"true\"><path d=\"M0 8h19M13 1l7 7-7 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"></path></svg></span><a class=\"faq-pill\" href=\"/faq\">Read the FAQs</a></span></span>\n  </div>\n  <a class=\"locker\" href=\"#fitness\" style=\"--c:var(--red)\">\n    <span class=\"ph\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/ref-smile.jpg\" alt=\"A smiling referee in a red kit walks onto the field at a national championship\" style=\"object-position:50% 22%\"></span>\n    <span class=\"tag\"><h2>Upgrades &amp; Fitness</h2><p>Go Regional. Next fitness test: Nov 19, Mesa.</p>\n      <span class=\"more\">Move up <svg width=\"22\" height=\"16\" viewBox=\"0 0 22 16\" aria-hidden=\"true\"><path d=\"M0 8h19M13 1l7 7-7 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"></path></svg></span></span>\n  </a>\n</div>\n\n<div class=\"intro\"><div class=\"wrap\">\n  <h1>Pick your color.</h1>\n  <div>\n    <p>Referees carry a shirt for every match. This site does too. Each part keeps its color on every page, so you always know where you are.</p>\n    <div class=\"key\">\n      <a href=\"#become\"><i style=\"--c:var(--yellow)\"></i>Get Certified</a>\n      <a href=\"#games\"><i style=\"--c:var(--green)\"></i>Find Games</a>\n      <a href=\"#resources\"><i style=\"--c:var(--blue)\"></i>Resources</a>\n      <a href=\"#fitness\"><i style=\"--c:var(--red)\"></i>Upgrades &amp; Fitness</a>\n    </div>\n  </div>\n</div></div>\n\n<section class=\"field y\" id=\"become\">\n  <div class=\"wrap\">\n    <div class=\"sec-title\"><h2>Become a Referee</h2><div class=\"st-r\"><p>Anyone 13 or older can do it. Never refereed before? The New Referee Course takes you from sign-up to badge in four steps.</p><a class=\"full\" href=\"/become-a-referee\">Full guide: becoming a referee <svg width=\"18\" height=\"13\" viewBox=\"0 0 22 16\" aria-hidden=\"true\"><path d=\"M0 8h19M13 1l7 7-7 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"></path></svg></a></div></div>\n    <div class=\"split\">\n      <div>\n        <ol class=\"steps\" id=\"steps\"></ol>\n        <div class=\"facts\"><span>Minimum age 13, no exceptions</span><span>License fee $80</span><span>18+: background check $24, every 2 years</span><span>Courses run Aug 1 – Mar 31</span></div>\n        <a class=\"hostcard\" href=\"https://request.azref.com/host/\"><span class=\"hc-ic\"><svg viewBox=\"0 0 48 48\" width=\"40\" height=\"40\" aria-hidden=\"true\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\" stroke-linejoin=\"round\"><rect x=\"4\" y=\"18\" width=\"40\" height=\"26\" rx=\"2\"></rect><path d=\"M24 18v26\"></path><circle cx=\"24\" cy=\"31\" r=\"5\"></circle><path d=\"M4 25h5v12H4M44 25h-5v12h5\"></path><path d=\"M24 14c-4-4-7-6.4-7-9.6A7 7 0 0 1 31 4.4c0 3.2-3 5.6-7 9.6z\" fill=\"currentColor\" stroke=\"none\"></path><circle cx=\"24\" cy=\"5\" r=\"2.4\" fill=\"var(--ink)\" stroke=\"none\"></circle></svg></span><span class=\"hc-t\"><small>Clubs, leagues &amp; schools</small><b>Host an in-person class</b><span>Got a field and a crowd of future referees? Bring a New Referee Course to your area. Tell us where and when and we'll take it from there.</span></span><em>Request a class</em></a>\n      </div>\n      <div class=\"panel\">\n        <div class=\"panel-h\"><h3>Next in-person classes</h3><a href=\"/become-a-referee#courses\">All 12 dates</a></div>\n        <ul class=\"rows\" id=\"courses\"></ul>\n        <a class=\"kitnudge\" href=\"#gear\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/capelli-black.png\" alt=\"Capelli Sport\"><span><b>Registered? Order your kit today.</b> Kits usually take 10 to 12 days to arrive, so order now and it's ready for your first games. Starter kits from $45.</span><em>Shop kits</em></a>\n      </div>\n      <a class=\"recert-card\" href=\"/recertify\"><b>Already a referee?</b><span>Recertify for 2027 online: about 5 hours, $80 all in.</span><em>Recertify now</em></a>\n    </div>\n  </div>\n</section>\n\n<section class=\"kitband\" id=\"gear\" aria-labelledby=\"gearH\"><div class=\"wrap\">\n  <div class=\"gear-head\">\n    <div>\n      <h2 id=\"gearH\">Get your kit</h2>\n      <p>ASRA's official kit partner is Capelli Sport. Our Arizona store has everything a new referee needs, and starter kits begin at $45. <mark>Order the day you register for your course: kits usually take 10 to 12 days to arrive.</mark></p>\n    </div>\n    <a class=\"gear-logo\" href=\"https://teams.us.capellisport.com/refarzad24/man100/mandatorykit\" aria-label=\"Capelli Sport, ASRA's official kit partner\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/capelli-black.png\" alt=\"Capelli Sport\"><span>Official kit partner</span></a>\n  </div>\n  <div class=\"kits\">\n    <a class=\"kit\" href=\"https://teams.us.capellisport.com/refarzad24/man100/mandatorykit\"><span class=\"kn\">Starter Kit #1</span><b>$45</b><ul><li>Yellow referee jersey</li><li>Shorts and socks</li><li>Whistle</li><li>Wallet with cards</li></ul><em>Shop kit #1</em></a>\n    <a class=\"kit pop\" href=\"https://teams.us.capellisport.com/refarzad24/man200/mandatorykit\"><span class=\"kn\">Starter Kit #2</span><b>$55</b><ul><li>Everything in kit #1</li><li>Assistant referee flags</li></ul><em>Shop kit #2</em></a>\n    <a class=\"kit\" href=\"https://teams.us.capellisport.com/refarzad24/man300/mandatorykit\"><span class=\"kn\">Starter Kit #3</span><b>$65</b><ul><li>Everything in kit #2</li><li>Sack pack to carry it all</li></ul><em>Shop kit #3</em></a>\n  </div>\n  <p class=\"gear-more\">Need more colors? The store also has other jerseys, training apparel, bags, footwear and cold-weather gear. <a href=\"https://teams.us.capellisport.com/refarzad24/man100/mandatorykit\">Shop the ASRA Capelli store</a></p>\n</div></section>\n\n<section class=\"field g\" id=\"games\">\n  <div class=\"wrap\">\n    <div class=\"sec-title\"><h2>Find Games</h2><div class=\"st-r\"><p>ASRA doesn't hand out games. Assignors do. Here's how a new referee gets on their list.</p><a class=\"full\" href=\"/assignors\">Assignor list <svg width=\"18\" height=\"13\" viewBox=\"0 0 22 16\" aria-hidden=\"true\"><path d=\"M0 8h19M13 1l7 7-7 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"></path></svg></a></div></div>\n    <div class=\"how\" id=\"how\"></div>\n    <form class=\"afind\" action=\"/assignors\" method=\"get\" role=\"search\">\n      <div><h3>Find an assignor</h3><p>Every league and area in Arizona, with the assignor's email.</p></div>\n      <label class=\"afind-in\"><span class=\"sr\">League, area or name</span><input name=\"q\" type=\"search\" placeholder=\"Open League, Tucson, RSL, USL…\" autocomplete=\"off\"></label>\n      <button class=\"btn\" type=\"submit\">Search</button>\n      <a class=\"full\" href=\"/assignors\">Full assignor list <svg width=\"18\" height=\"13\" viewBox=\"0 0 22 16\" aria-hidden=\"true\"><path d=\"M0 8h19M13 1l7 7-7 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"></path></svg></a>\n    </form>\n    <div class=\"leagues\" id=\"leagues\"></div>\n    <div class=\"panel cal\" id=\"calendar\">\n      <div class=\"cal-top\">\n        <div><h3>Events Calendar</h3><p class=\"cal-sub\">Tournaments, leagues, club, regional and national events · 2026–27 season</p></div>\n        <div class=\"seg\" role=\"group\" aria-label=\"How much to show\">\n          <button type=\"button\" class=\"seg-b\" data-view=\"month\" aria-pressed=\"true\">By Month</button>\n          <button type=\"button\" class=\"seg-b\" data-view=\"season\" aria-pressed=\"false\">Whole Season</button>\n        </div>\n      </div>\n      <div class=\"cal-tools\">\n        <div class=\"filter\" role=\"group\" aria-label=\"Filter by your level\">\n          <button class=\"chip\" type=\"button\" data-lv=\"all\" aria-pressed=\"true\">All Levels</button>\n          <button class=\"chip\" type=\"button\" data-lv=\"green\" aria-pressed=\"false\"></button>\n          <button class=\"chip\" type=\"button\" data-lv=\"blue\" aria-pressed=\"false\"></button>\n          <button class=\"chip\" type=\"button\" data-lv=\"black\" aria-pressed=\"false\"></button>\n          <button class=\"chip\" type=\"button\" data-lv=\"double\" aria-pressed=\"false\"></button>\n          <button class=\"chip open\" type=\"button\" id=\"openOnly\" aria-pressed=\"false\"><span class=\"dot\" aria-hidden=\"true\"></span>Sign-Up Open</button>\n        </div>\n        <label class=\"search\"><span class=\"sr\">Search events</span><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\"></circle><path d=\"M15.5 15.5 21 21\" stroke=\"currentColor\" stroke-width=\"2.4\"></path></svg><input id=\"q\" type=\"search\" placeholder=\"Search event, city or assignor\" autocomplete=\"off\"></label>\n      </div>\n      <div class=\"months\" id=\"months\" role=\"tablist\" aria-label=\"Months\"></div>\n      <div class=\"cal-meta\"><p id=\"summary\" aria-live=\"polite\"></p><label class=\"past\"><input type=\"checkbox\" id=\"showPast\"> Show finished events</label></div>\n      <div id=\"events\"></div>\n      <div class=\"legend\" id=\"legend\"></div>\n    </div>\n  </div>\n</section>\n\n<section class=\"field r\" id=\"fitness\">\n  <div class=\"wrap fit-grid\">\n    <div class=\"ph\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/ref-signal.jpg\" alt=\"A referee in an orange kit signals during a youth match\"></div>\n    <div>\n      <h2 style=\"font-size:clamp(52px,7vw,96px);text-transform:uppercase\">Upgrades &amp; Fitness</h2>\n      <div class=\"upg\">\n        <h3>Ready to go Regional?</h3>\n        <p>The Regional badge opens up the Elite (double-diamond) events on the calendar and higher-level assignments. See every requirement, step by step, first time or recertifying.</p>\n        <div class=\"upg-go\"><a class=\"btn\" href=\"/regional\">Regional requirements <svg width=\"18\" height=\"13\" viewBox=\"0 0 22 16\" aria-hidden=\"true\"><path d=\"M0 8h19M13 1l7 7-7 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"></path></svg></a><a class=\"btn ghost\" href=\"/national\">National</a><a class=\"btn ghost\" href=\"/licenses\">Every license</a></div>\n      </div>\n      <div style=\"display:flex;justify-content:space-between;align-items:baseline;gap:12px;flex-wrap:wrap\"><h3 class=\"ft-h\">Upcoming fitness tests</h3><a class=\"full\" href=\"/fitness\">How the test works <svg width=\"18\" height=\"13\" viewBox=\"0 0 22 16\" aria-hidden=\"true\"><path d=\"M0 8h19M13 1l7 7-7 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"></path></svg></a></div>\n      <p style=\"margin:6px 0 0;font-size:17px;font-weight:700;max-width:52ch\">For Regional referees and Regional candidates. Pass it in the current or previous registration year. Arrive 35 minutes early.</p>\n      <div class=\"tests\" id=\"tests\"></div>\n    </div>\n  </div>\n</section>\n\n<section class=\"field b pitch\" id=\"resources\">\n  <div class=\"wrap\">\n    <div class=\"sec-title\"><h2>Resources</h2>\n      <div class=\"rstack\" aria-hidden=\"true\">\n        <figure class=\"rcard c1\" style=\"--t:var(--yellow)\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/res-learn.jpg\" alt=\"\" loading=\"lazy\"><figcaption>Learn it</figcaption></figure>\n        <figure class=\"rcard c2\" style=\"--t:var(--green)\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/res-crew.jpg\" alt=\"\" loading=\"lazy\"><figcaption>Work it</figcaption></figure>\n        <figure class=\"rcard c3\" style=\"--t:var(--red)\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/res-ar.jpg\" alt=\"\" loading=\"lazy\"><figcaption>Grow it</figcaption></figure>\n      </div>\n      <div class=\"st-r\"><p>Every form, list and rulebook, grouped by what you're trying to get done.</p><a class=\"full\" href=\"#page-resources\">All resources <svg width=\"18\" height=\"13\" viewBox=\"0 0 22 16\" aria-hidden=\"true\"><path d=\"M0 8h19M13 1l7 7-7 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"></path></svg></a></div></div>\n    <div class=\"res\" id=\"res\"></div>\n  </div>\n</section>\n\n<section class=\"rtc\" aria-labelledby=\"rtcH\"><div class=\"wrap\">\n  <div class=\"rtc-art\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/rap-np2.jpg\" alt=\"U.S. Soccer Respect the Call illustration: a coach yells at a young assistant referee holding his flag. Harassment carries a minimum 4-game suspension.\" loading=\"lazy\"></div>\n  <div>\n    <h2 id=\"rtcH\">Stop referee abuse</h2>\n    <p>U.S. Soccer's Referee Abuse Prevention policy sets minimum suspensions for anyone who abuses a referee, from one game for taunting to a lifetime ban for violent contact. It only works when abuse gets reported.</p>\n    <div class=\"rtc-facts\"><span><b>1 game</b> minimum for taunting</span><span><b>2 to 3 times</b> the penalty when an adult targets a young ref</span><span><b>48 hours</b>: report it within two days if you can</span></div>\n    <div class=\"rtc-go\"><a class=\"btn rd\" href=\"https://request.azref.com/abuse/\">Report abuse</a><a class=\"btn lt\" href=\"/referee-abuse\">Read about the policy</a></div>\n  </div>\n</div></section>\n\n<section class=\"news\"><div class=\"wrap\">\n  <div><h2>News</h2><a class=\"all\" href=\"/news\">All news <svg width=\"18\" height=\"13\" viewBox=\"0 0 22 16\" aria-hidden=\"true\"><path d=\"M0 8h19M13 1l7 7-7 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"/></svg></a></div>\n  <ul id=\"news\"></ul>\n</div></section>\n</main>\n\n<section class=\"askus\" aria-labelledby=\"askH\"><div class=\"wrap\">\n  <div class=\"faces\" aria-hidden=\"true\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/board/joel-votaw.jpg\" alt=\"\" style=\"--c:var(--yellow)\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/board/mitchell-christensen.jpg\" alt=\"\" style=\"--c:var(--green)\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/board/jason-ulrich.jpg\" alt=\"\" style=\"--c:var(--blue)\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/board/melissa-beck.jpg\" alt=\"\" style=\"--c:var(--red)\"></div>\n  <div><h2 id=\"askH\">Questions? Real people answer.</h2><p>Stuck on the Learning Center, a license, or finding games? Send us a note and someone on the ASRA team gets back to you. Email <a href=\"mailto:admin@azref.com\">admin@azref.com</a> or text <a href=\"sms:+14809135345\">480-913-5345</a>.</p></div>\n  <div class=\"go\"><a href=\"/contact\">Contact us</a><a class=\"alt\" href=\"/faq\">Read the FAQs</a></div>\n</div></section>\n\n<footer id=\"about\">\n  <div class=\"stripe\" aria-hidden=\"true\"><i style=\"--c:var(--yellow)\"></i><i style=\"--c:var(--green)\"></i><i style=\"--c:var(--blue)\"></i><i style=\"--c:var(--red)\"></i><i style=\"--c:#fff\"></i></div>\n  <div class=\"wrap\">\n    <div><h3>Arizona State Referee Administration</h3><p>The US Soccer State Referee Committee for Arizona. Kits and gear from our official partner, Capelli Sport.</p><a class=\"foot-partner\" href=\"https://teams.us.capellisport.com/refarzad24/man100/mandatorykit\"><img src=\"https://cdn.jsdelivr.net/gh/AZREFEREE/azref-site-files@main/img/capelli-white.png\" alt=\"Capelli Sport, official kit partner\"></a><p>Email <a class=\"sel\" href=\"mailto:admin@azref.com\" style=\"display:inline\">admin@azref.com</a><br>Text <a class=\"sel\" href=\"sms:+14809135345\" style=\"display:inline\">480-913-5345</a></p><a class=\"foot-contact\" href=\"/contact\">Send us a message</a></div>\n    <div><h3>Get around</h3><a href=\"#become\">Become a Referee</a><a href=\"#games\">Find Games</a><a href=\"#resources\">Resources</a><a href=\"/fitness\">Fitness tests</a><a href=\"/licenses\">Every license</a></div>\n    <div><h3>The committee</h3><a href=\"/about\">About ASRA</a><a href=\"/news\">News</a><a href=\"/about#directors\">Directors</a><a href=\"/contact\">Contact us</a><a href=\"/contact?topic=recognize\">Recognize a ref</a><a href=\"#gear\">Kits from Capelli Sport</a><a href=\"/referee-abuse\">Referee abuse policy</a><a href=\"https://request.azref.com/abuse/\">Report abuse</a></div>\n  </div>\n</footer>";
