/* Trail-map difficulty symbols, drawn as SVG (never emoji). */
window.ASRA.runIcon = function (level, size) {
  size = size || 16;
  var c = { green: "#1f9d55", blue: "#1f5fd1", black: "#111", double: "#111" }[level];
  var t = window.ASRA.levels[level].name;
  var s;
  if (level === "green") s = '<circle cx="8" cy="8" r="7" fill="' + c + '"/>';
  else if (level === "blue") s = '<rect x="1.5" y="1.5" width="13" height="13" fill="' + c + '"/>';
  else if (level === "black") s = '<path d="M8 .8 15.2 8 8 15.2.8 8Z" fill="' + c + '"/>';
  else s = '<path d="M5 1.5 9.5 8 5 14.5.5 8Z M13 1.5 17.5 8 13 14.5 8.5 8Z" fill="' + c + '"/>';
  var w = level === "double" ? 18 : 16;
  return '<svg class="run run-' + level + '" width="' + (size * w / 16) + '" height="' + size + '" viewBox="0 0 ' + w + ' 16" role="img" aria-label="' + t + '"><title>' + t + '</title>' + s + '</svg>';
};
window.ASRA.runsHtml = function (runs, size) {
  return runs.map(function (r) { return window.ASRA.runIcon(r, size); }).join("");
};

