  /* Link rewriting: mockup file names (become.html, license.html?l=x&t=y ...) -> Wix paths.
   Used at build time (node, for the static markup) and at runtime (inside every kb-<page> element,
   for links the page scripts and CMS content create). Keep it ES5. */
function KBLinks(ROUTES) {
  /* Placeholder values used when a query parameter is missing. A license with no ?t= is the "new" track. */
  var DEFAULTS = { t: 'new' };
  /* When a required placeholder is missing entirely, fall back to the parent page. */
  var MISSING = { l: '/licenses', e: '/webinars' };
  var RE = /^(?:\.\/)?([a-z0-9][a-z0-9_-]*)\.html(\?[^#]*)?(#.*)?$/i;

  function parseQuery(q) {
    var out = [];
    String(q || '').replace(/^\?/, '').split('&').forEach(function (kv) {
      if (!kv) return;
      var i = kv.indexOf('='), k = i < 0 ? kv : kv.slice(0, i), v = i < 0 ? '' : kv.slice(i + 1);
      var dk; try { dk = decodeURIComponent(k.replace(/\+/g, ' ')); } catch (e) { dk = k; }
      out.push([dk, kv]);
    });
    return out;
  }
  function getQ(pairs, key) {
    for (var i = 0; i < pairs.length; i++) if (pairs[i][0] === key) {
      var raw = pairs[i][1], j = raw.indexOf('=');
      var v = j < 0 ? '' : raw.slice(j + 1);
      try { return decodeURIComponent(v.replace(/\+/g, ' ')); } catch (e) { return v; }
    }
    return null;
  }

  /** toWix('license.html?l=referee&t=returning#x') -> '/licenses/referee/returning#x'. Anything else is returned unchanged. */
  function toWix(href) {
    if (href == null) return href;
    var s = String(href).trim();
    if (s === './' || s === '.' || s === './index.html' || s === 'index.html') return ROUTES['kit-bag'] || '/';
    var m = s.match(RE);
    if (!m) return href;
    var page = m[1].toLowerCase(), tpl = ROUTES[page];
    if (tpl == null) return href;           // not one of our pages (old mockups etc.): leave it alone
    var pairs = parseQuery(m[2]), used = {}, missing = null;
    var path = tpl.replace(/\{([a-z]+)\}/gi, function (_, k) {
      used[k] = true;
      var v = getQ(pairs, k);
      if (v == null || v === '') v = DEFAULTS[k];
      if (v == null || v === '') { missing = missing || k; return ''; }
      return encodeURIComponent(v);
    });
    if (missing) path = MISSING[missing] || '/';
    var rest = pairs.filter(function (p) { return !used[p[0]]; }).map(function (p) { return p[1]; });
    return path + (rest.length ? (path.indexOf('?') >= 0 ? '&' : '?') + rest.join('&') : '') + (m[3] || '');
  }
  return { toWix: toWix };
}

